int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> seen = new HashMap<>();
    seen.put(0, 1);
    int prefix = 0, count = 0;
    for (int i = 0; i < nums.length; i++) {
        prefix += nums[i];
        int add = seen.getOrDefault(prefix - k, 0);
        count += add;
        seen.merge(prefix, 1, Integer::sum);
    }
    return count;
}

