def findAnagrams(s: str, p: str) -> List[int]:
    res = []
    if len(p) > len(s): return res
    need, win = Counter(p), Counter()
    for i, c in enumerate(s):
        win[c] += 1
        if i >= len(p):
            old = s[i - len(p)]
            win[old] -= 1
            if win[old] == 0: del win[old]
        if i >= len(p) - 1 and win == need: res.append(i - len(p) + 1)
    return res

